import PDFDocument from "pdfkit";
import { prisma } from "../config/database.js";
import { ApiError } from "../utils/api-error.js";
import { parseDateOnly, toAmount, toDateOnly } from "../utils/format.js";
import { toContributionDTO } from "./contributions.service.js";
import { toLoanDTO } from "./loans.service.js";

/**
 * Statements are generated purely from RECORDED data (contribution records,
 * loan register, repayment records). They are not bank statements and say so.
 */

export interface StatementQuery {
  from?: string;
  to?: string;
}

const DISCLAIMER =
  "Generated by Pamoja Wealth from records entered by your chama's officers. " +
  "Pamoja does not hold, receive or transfer money; verify against the chama's own M-Pesa/bank statements.";

export async function build(chamaId: string, memberId: string | null, query: StatementQuery) {
  const chama = await prisma.chama.findUnique({ where: { id: chamaId }, select: { id: true, name: true } });
  if (!chama) throw ApiError.notFound("Chama");

  let member: { userId: string; fullName: string } | undefined;
  if (memberId) {
    const m = await prisma.membership.findUnique({
      where: { userId_chamaId: { userId: memberId, chamaId } },
      include: { user: { select: { fullName: true } } },
    });
    if (!m) throw ApiError.notFound("Member");
    member = { userId: memberId, fullName: m.user.fullName };
  }

  const dateRange =
    query.from || query.to
      ? { ...(query.from && { gte: parseDateOnly(query.from) }), ...(query.to && { lte: parseDateOnly(query.to) }) }
      : undefined;

  const [contributions, loans, repayments] = await Promise.all([
    prisma.contributionRecord.findMany({
      where: { chamaId, status: { not: "voided" }, ...(memberId && { memberId }), ...(dateRange && { paidOn: dateRange }) },
      include: { member: { select: { fullName: true } }, recordedBy: { select: { fullName: true } } },
      orderBy: { paidOn: "asc" },
    }),
    prisma.loan.findMany({
      where: {
        chamaId,
        recordedById: { not: null },
        ...(memberId && { borrowerId: memberId }),
        ...(dateRange && { issuedOn: dateRange }),
      },
      include: { borrower: { select: { fullName: true } } },
      orderBy: { issuedOn: "asc" },
    }),
    prisma.loanRepaymentRecord.findMany({
      where: { chamaId, ...(memberId && { loan: { borrowerId: memberId } }), ...(dateRange && { paidOn: dateRange }) },
      include: { loan: { include: { borrower: { select: { fullName: true } } } }, recordedBy: { select: { fullName: true } } },
      orderBy: { paidOn: "asc" },
    }),
  ]);

  const contributionDTOs = contributions.map(toContributionDTO);
  const loanDTOs = loans.map(toLoanDTO);
  const repaymentDTOs = repayments.map((r) => ({
    id: r.id,
    loanId: r.loanId,
    borrowerName: r.loan.borrower.fullName,
    amount: toAmount(r.amount),
    paidOn: toDateOnly(r.paidOn),
    method: r.method,
    mpesaReceipt: r.mpesaReceipt,
    note: r.note,
    recordedByName: r.recordedBy.fullName,
    createdAt: r.createdAt.toISOString(),
  }));

  const round = (n: number) => Math.round(n * 100) / 100;
  return {
    chama,
    ...(member && { member }),
    period: { from: query.from ?? null, to: query.to ?? null },
    generatedAt: new Date().toISOString(),
    disclaimer: DISCLAIMER,
    contributions: contributionDTOs,
    loans: loanDTOs,
    repayments: repaymentDTOs,
    totals: {
      contributions: round(contributionDTOs.reduce((s, c) => s + c.amount, 0)),
      loansIssued: round(loanDTOs.reduce((s, l) => s + l.principal, 0)),
      repayments: round(repaymentDTOs.reduce((s, r) => s + r.amount, 0)),
    },
  };
}

export type Statement = Awaited<ReturnType<typeof build>>;

/** Escape a CSV cell, neutralising spreadsheet formula injection. */
export function csvCell(value: unknown): string {
  let s = value === null || value === undefined ? "" : String(value);
  if (/^[=+\-@\t\r]/.test(s)) s = `'${s}`;
  return /[",\n\r]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
}

export function toCsv(st: Statement): string {
  const rows: unknown[][] = [
    ["Statement", st.member ? `${st.chama.name} — ${st.member.fullName}` : st.chama.name],
    ["Period", `${st.period.from ?? "start"} to ${st.period.to ?? "today"}`],
    ["Generated", st.generatedAt],
    ["Note", st.disclaimer],
    [],
    ["Type", "Date", "Member", "Amount (KES)", "Method", "M-Pesa receipt", "Status", "Recorded by", "Reference"],
  ];
  for (const c of st.contributions) {
    rows.push(["Contribution", c.paidOn, c.memberName, c.amount.toFixed(2), c.method, c.mpesaReceipt, c.status, c.recordedByName, c.id]);
  }
  for (const l of st.loans) {
    rows.push(["Loan issued (from chama account)", l.issuedOn, l.borrowerName, l.principal.toFixed(2), "", "", l.status, "", l.id]);
  }
  for (const r of st.repayments) {
    rows.push(["Loan repayment", r.paidOn, r.borrowerName, r.amount.toFixed(2), r.method, r.mpesaReceipt, "", r.recordedByName, r.loanId]);
  }
  rows.push([]);
  rows.push(["Total contributions", "", "", st.totals.contributions.toFixed(2)]);
  rows.push(["Total loans issued", "", "", st.totals.loansIssued.toFixed(2)]);
  rows.push(["Total repayments", "", "", st.totals.repayments.toFixed(2)]);
  return rows.map((r) => r.map(csvCell).join(",")).join("\r\n") + "\r\n";
}

export function toPdf(st: Statement): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    const doc = new PDFDocument({ size: "A4", margin: 40 });
    const chunks: Buffer[] = [];
    doc.on("data", (c: Buffer) => chunks.push(c));
    doc.on("end", () => resolve(Buffer.concat(chunks)));
    doc.on("error", reject);

    const kes = (n: number) => `KES ${n.toLocaleString("en-KE", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

    doc.fontSize(16).text(st.member ? `Member statement — ${st.member.fullName}` : "Chama statement");
    doc.fontSize(11).text(st.chama.name);
    doc.fontSize(9).fillColor("#555").text(`Period: ${st.period.from ?? "start"} to ${st.period.to ?? "today"}   ·   Generated ${st.generatedAt.slice(0, 10)}`);
    doc.moveDown(0.5).text(st.disclaimer);
    doc.fillColor("#000").moveDown();

    const section = (title: string, lines: string[]) => {
      doc.fontSize(12).text(title, { underline: true });
      doc.fontSize(9);
      if (lines.length === 0) doc.text("None recorded.");
      for (const line of lines) doc.text(line);
      doc.moveDown();
    };

    section(
      "Contributions",
      st.contributions.map(
        (c) => `${c.paidOn}  ${c.memberName}  ${kes(c.amount)}  ${c.method}${c.mpesaReceipt ? ` (${c.mpesaReceipt})` : ""}  [${c.status}]`,
      ),
    );
    section(
      "Loans issued from the chama's account",
      st.loans.map((l) => `${l.issuedOn}  ${l.borrowerName}  ${kes(l.principal)}  balance ${kes(l.balance)}  [${l.status}]`),
    );
    section(
      "Loan repayments",
      st.repayments.map((r) => `${r.paidOn}  ${r.borrowerName}  ${kes(r.amount)}  ${r.method}${r.mpesaReceipt ? ` (${r.mpesaReceipt})` : ""}`),
    );
    doc.fontSize(11).text(`Total contributions: ${kes(st.totals.contributions)}`);
    doc.text(`Total loans issued: ${kes(st.totals.loansIssued)}`);
    doc.text(`Total repayments: ${kes(st.totals.repayments)}`);
    doc.end();
  });
}
